export interface OrderLine {
  slug: string
  name: string
  qty: number
}

/** An order as returned by `GET /api/orders/:id`. Amounts use the quote format, e.g. `19.99 USD`. */
export interface Order {
  id: string
  lines: OrderLine[]
  subtotal: string
  discount: string
  total: string
}

import type { CartLine } from '#shared/types/cart'
import type { Order, OrderLine } from '#shared/types/order'
import { randomUUID } from 'node:crypto'
import { findProduct } from '#server/utils/db'
import { computeQuote } from '#server/utils/quote'

/** Orders live in server memory only, so they are lost on restart. */
const orders = new Map<string, Order>()

/** Stores an order priced by the same quote logic as `/api/cart/quote`. Lines are snapshotted with product names. */
export function createOrder(lines: CartLine[], code?: string): Order {
  const quote = computeQuote(lines, code)
  const order: Order = {
    id: randomUUID(),
    lines: lines.map((line): OrderLine => ({
      slug: line.slug,
      name: findProduct(line.slug)?.name ?? line.slug,
      qty: line.qty,
    })),
    ...quote,
  }
  orders.set(order.id, order)
  return order
}

export function getOrder(id: string): Order | undefined {
  return orders.get(id)
}

import type { CartLine } from '#shared/types/cart'
import { createError, defineEventHandler, readBody } from 'h3'
import { findProduct } from '#server/utils/db'
import { createOrder } from '#server/utils/orders'

export default defineEventHandler(async (event) => {
  const body = await readBody<{ lines?: CartLine[], code?: string }>(event)
  const lines = body?.lines
  if (!Array.isArray(lines) || lines.length === 0)
    throw createError({ statusCode: 400, statusMessage: 'Order needs at least one line' })
  for (const line of lines) {
    if (!findProduct(line?.slug ?? ''))
      throw createError({ statusCode: 400, statusMessage: `Unknown product: ${line?.slug}` })
    if (!Number.isInteger(line.qty) || line.qty < 1)
      throw createError({ statusCode: 400, statusMessage: 'Quantity must be a positive integer' })
  }
  const { id, subtotal, discount, total } = createOrder(lines, body?.code)
  return { id, subtotal, discount, total }
})

import { createError, defineEventHandler, getRouterParam } from 'h3'
import { getOrder } from '#server/utils/orders'

export default defineEventHandler((event) => {
  const order = getOrder(getRouterParam(event, 'id') ?? '')
  if (!order)
    throw createError({ statusCode: 404, statusMessage: 'Order not found' })
  return order
})
